/* WebGL renderer and interaction for the 3D market view.
 *
 * Plain WebGL 1, no libraries, no CDN. The page is served from the research server, which
 * has no outbound network at runtime, so every shader is inline and every vertex is
 * generated by scene-math.js. If a context cannot be created the caller is told so and the
 * page falls back to the flat table instead of showing a broken canvas.
 */
'use strict';

(function () {
  const Math3 = (typeof window !== 'undefined' ? window.SceneMath : null);
  if (!Math3) return;

  const VERTEX_SHADER = [
    'attribute vec3 aPosition;',
    'attribute vec3 aNormal;',
    'attribute vec3 aColor;',
    'uniform mat4 uViewProjection;',
    'uniform vec3 uLight;',
    'varying vec3 vColor;',
    'varying float vDepth;',
    'void main() {',
    '  vec4 clip = uViewProjection * vec4(aPosition, 1.0);',
    '  float lambert = max(dot(normalize(aNormal), normalize(uLight)), 0.0);',
    '  float rim = 0.44 + 0.62 * lambert;',
    '  vColor = aColor * rim;',
    '  vDepth = clamp(-clip.z / 42.0, 0.0, 1.0);',
    '  gl_Position = clip;',
    '}',
  ].join('\n');

  const FRAGMENT_SHADER = [
    'precision mediump float;',
    'varying vec3 vColor;',
    'varying float vDepth;',
    'void main() {',
    '  vec3 fogged = mix(vColor, vec3(0.031, 0.047, 0.071), vDepth * 0.55);',
    '  gl_FragColor = vec4(fogged, 1.0);',
    '}',
  ].join('\n');

  const LINE_FRAGMENT_SHADER = [
    'precision mediump float;',
    'varying vec3 vColor;',
    'varying float vDepth;',
    'void main() {',
    '  float fade = 1.0 - vDepth * 0.85;',
    '  gl_FragColor = vec4(vColor, fade * 0.55);',
    '}',
  ].join('\n');

  function compile(gl, type, source) {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      const log = gl.getShaderInfoLog(shader);
      gl.deleteShader(shader);
      throw new Error('shader compile failed: ' + log);
    }
    return shader;
  }

  function program(gl, vertexSource, fragmentSource) {
    const prog = gl.createProgram();
    gl.attachShader(prog, compile(gl, gl.VERTEX_SHADER, vertexSource));
    gl.attachShader(prog, compile(gl, gl.FRAGMENT_SHADER, fragmentSource));
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
      throw new Error('shader link failed: ' + gl.getProgramInfoLog(prog));
    }
    return prog;
  }

  function buffer(gl, data) {
    const result = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, result);
    gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
    return result;
  }

  function MarketScene(canvas) {
    this.canvas = canvas;
    this.gl = null;
    this.state = { azimuth: 0.55, elevation: 0.45, radius: 9.0, autoRotate: true };
    this.tracks = [];
    this.frames = 0;
    this.lastFrameAt = 0;
    this.drag = null;
  }

  MarketScene.prototype.init = function init() {
    const options = { antialias: true, alpha: false, depth: true, powerPreference: 'default' };
    const gl = this.canvas.getContext('webgl', options) ||
               this.canvas.getContext('experimental-webgl', options);
    if (!gl) return false;
    this.gl = gl;

    this.solid = program(gl, VERTEX_SHADER, FRAGMENT_SHADER);
    this.solidAttribs = {
      position: gl.getAttribLocation(this.solid, 'aPosition'),
      normal: gl.getAttribLocation(this.solid, 'aNormal'),
      color: gl.getAttribLocation(this.solid, 'aColor'),
    };
    this.solidUniforms = {
      viewProjection: gl.getUniformLocation(this.solid, 'uViewProjection'),
      light: gl.getUniformLocation(this.solid, 'uLight'),
    };
    this.lineProgram = program(gl, VERTEX_SHADER, LINE_FRAGMENT_SHADER);
    this.lineAttribs = {
      position: gl.getAttribLocation(this.lineProgram, 'aPosition'),
      normal: gl.getAttribLocation(this.lineProgram, 'aNormal'),
      color: gl.getAttribLocation(this.lineProgram, 'aColor'),
    };
    this.lineUniforms = {
      viewProjection: gl.getUniformLocation(this.lineProgram, 'uViewProjection'),
      light: gl.getUniformLocation(this.lineProgram, 'uLight'),
    };

    gl.enable(gl.DEPTH_TEST);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.clearColor(0.031, 0.047, 0.071, 1.0);
    this.bindInteractions();
    return true;
  };

  MarketScene.prototype.setData = function setData(feeds) {
    const gl = this.gl;
    if (!gl) return;
    const geometry = Math3.buildTracks(feeds || [], { maxCandles: 90 });
    this.geometry = geometry;
    this.tracks = geometry.tracks;
    this.candleBuffer = buffer(gl, geometry.positions);
    this.candleNormals = buffer(gl, geometry.normals);
    this.candleColors = buffer(gl, geometry.colors);
    const grid = Math3.buildGrid({ lines: 16, step: 0.85 });
    this.gridBuffer = buffer(gl, grid.positions);
    this.gridColors = buffer(gl, grid.colors);
    this.gridVertexCount = grid.positions.length / 3;
    this.frameCameraToTracks();
  };

  MarketScene.prototype.trackCentreZ = function trackCentreZ() {
    if (!this.tracks || !this.tracks.length) return 0;
    const zs = this.tracks.map((track) => track.z);
    return (Math.min.apply(null, zs) + Math.max.apply(null, zs)) / 2;
  };

  MarketScene.prototype.frameCameraToTracks = function frameCameraToTracks() {
    // Fit the widest track across the horizontal field of view, then step back a little
    // for the depth of the other tracks and the vertical room a candle body needs.
    const widest = (this.tracks || []).reduce((max, track) => Math.max(max, track.width || 0), 0);
    this.state.radius = Math.max(4.2, Math.min(11.5, widest * 0.8 + 1.8));
  };

  MarketScene.prototype.bindInteractions = function bindInteractions() {
    const self = this;
    const canvas = this.canvas;
    canvas.addEventListener('pointerdown', function (event) {
      self.drag = { x: event.clientX, y: event.clientY, azimuth: self.state.azimuth,
                    elevation: self.state.elevation };
      self.state.autoRotate = false;
      canvas.setPointerCapture(event.pointerId);
    });
    canvas.addEventListener('pointermove', function (event) {
      if (!self.drag) return;
      self.state.azimuth = self.drag.azimuth - (event.clientX - self.drag.x) * 0.006;
      self.state.elevation = Math.max(-0.25, Math.min(1.25,
        self.drag.elevation + (event.clientY - self.drag.y) * 0.005));
    });
    const release = function () { self.drag = null; };
    canvas.addEventListener('pointerup', release);
    canvas.addEventListener('pointercancel', release);
    canvas.addEventListener('pointerleave', release);
    canvas.addEventListener('wheel', function (event) {
      event.preventDefault();
      self.state.radius = Math.max(3.2, Math.min(26, self.state.radius + event.deltaY * 0.006));
    }, { passive: false });
    canvas.addEventListener('dblclick', function () {
      self.state.autoRotate = !self.state.autoRotate;
      if (self.onToggleRotate) self.onToggleRotate(self.state.autoRotate);
    });
  };

  MarketScene.prototype.render = function render(now) {
    const gl = this.gl;
    if (!gl) return;
    const width = this.canvas.width;
    const height = this.canvas.height;
    gl.viewport(0, 0, width, height);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

    if (this.state.autoRotate) this.state.azimuth += 0.0016;
    const centre = [0, 0.62, 0];
    const eye = Math3.orbitEye(centre, this.state.azimuth, this.state.elevation, this.state.radius);
    const projection = Math3.perspective(42, width / Math.max(1, height), 0.1, 120);
    const view = Math3.lookAt(eye, centre, [0, 1, 0]);
    const viewProjection = Math3.multiply(projection, view);
    this.viewProjection = viewProjection;
    const light = [0.35, 0.9, 0.45];

    if (this.gridBuffer) {
      gl.useProgram(this.lineProgram);
      gl.uniformMatrix4fv(this.lineUniforms.viewProjection, false, viewProjection);
      gl.uniform3fv(this.lineUniforms.light, light);
      this.attach(gl, this.lineAttribs, this.gridBuffer, null, this.gridColors);
      gl.drawArrays(gl.LINES, 0, this.gridVertexCount);
    }

    if (this.candleBuffer) {
      gl.useProgram(this.solid);
      gl.uniformMatrix4fv(this.solidUniforms.viewProjection, false, viewProjection);
      gl.uniform3fv(this.solidUniforms.light, light);
      this.attach(gl, this.solidAttribs, this.candleBuffer, this.candleNormals, this.candleColors);
      gl.drawArrays(gl.TRIANGLES, 0, this.geometry.vertexCount);
    }
    this.frames += 1;
    this.lastFrameAt = now || 0;
    if (this.onFrame) this.onFrame(this.frames);
  };

  /* Where a world point lands on the canvas, in CSS pixels, or null when it is behind
   * the camera. boot.js uses this to float price tags over the newest candle. */
  MarketScene.prototype.projectPoint = function projectPoint(point) {
    if (!this.viewProjection) return null;
    const ndc = Math3.project(this.viewProjection, point);
    if (ndc[3] <= 0.0001) return null;
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (ndc[0] * 0.5 + 0.5) * rect.width,
      y: (1 - (ndc[1] * 0.5 + 0.5)) * rect.height,
      visible: Math.abs(ndc[0]) <= 1.05 && Math.abs(ndc[1]) <= 1.05,
    };
  };

  MarketScene.prototype.attach = function attach(gl, attribs, positionBuffer, normalBuffer,
                                                 colorBuffer) {
    gl.bindBuffer(gl.ARRAY_BUFFER, positionBuffer);
    gl.enableVertexAttribArray(attribs.position);
    gl.vertexAttribPointer(attribs.position, 3, gl.FLOAT, false, 0, 0);
    if (normalBuffer) {
      gl.bindBuffer(gl.ARRAY_BUFFER, normalBuffer);
      gl.enableVertexAttribArray(attribs.normal);
      gl.vertexAttribPointer(attribs.normal, 3, gl.FLOAT, false, 0, 0);
    } else {
      gl.disableVertexAttribArray(attribs.normal);
      gl.vertexAttrib3f(attribs.normal, 0, 1, 0);
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, colorBuffer);
    gl.enableVertexAttribArray(attribs.color);
    gl.vertexAttribPointer(attribs.color, 3, gl.FLOAT, false, 0, 0);
  };

  MarketScene.prototype.resize = function resize() {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const width = Math.max(1, Math.round(rect.width * dpr));
    const height = Math.max(1, Math.round(rect.height * dpr));
    if (this.canvas.width !== width || this.canvas.height !== height) {
      this.canvas.width = width;
      this.canvas.height = height;
    }
  };

  function start(canvas) {
    const scene = new MarketScene(canvas);
    if (!scene.init()) return null;
    return scene;
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { MarketScene, start, VERTEX_SHADER, FRAGMENT_SHADER };
  }
  if (typeof window !== 'undefined') {
    window.MarketScene = MarketScene;
    window.startMarketScene = start;
  }
})();
